mapper.select:
SELECT COUNT(*)
FROM food_submission_requests
WHERE submitted_by_user_id = #{userId}

SELECT

FROM food_submission_requests fsr
JOIN users u
    ON u.id = fsr.submitted_by_user_id
WHERE fsr.submitted_by_user_id = #{userId}
ORDER BY fsr.submitted_at DESC, fsr.id DESC
LIMIT #{limit}
OFFSET #{offset}

SELECT COUNT(*)
FROM food_submission_requests
WHERE status = #{status}

SELECT

FROM food_submission_requests fsr
JOIN users u
    ON u.id = fsr.submitted_by_user_id
WHERE fsr.status = #{status}
ORDER BY fsr.submitted_at DESC, fsr.id DESC
LIMIT #{limit}
OFFSET #{offset}
